"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[42159],{42159:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/behind-doors.png\\"\\n          title=\\"비하인드 도어\\"\\n          author=\\"B. A. 패리스\\"\\n          publisher=\\"모모\\"\\n          publishedDate=\\"2021-12-06\\"\\n          isbn=\\"9791191043525\\"\\n          rating=3.5\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\n여자 주인공의 절망스러운 감정과 공포가 고스란히 느껴진다.  \\n책을 읽는 내내 답답한 마음이었다. 빠져나갈 수 없는 덫에 걸린 기분이랄까?  \\n<br>\\n우리가 모르는 세상에도 비슷한 사례가 많이 있을 것 같다. 아니, 분명 있다. 단지 사건이 터지기 전까지 우리가 인지하지 못하고 있는 것일 것이다.  \\n<br>\\n하지만 누군가 그런 상황에 처해 있다고 해도 내가 도울 수 있는 용기가 있을까 생각해 본다."}')}}]);